    DL([("Buurvrouw","Vind je het erg dat ik even je ladder leen?","Importas-te que te peça o escadote emprestado?"),("Jij","","")], ["*Nee hoor, pak hem maar.","Ja hoor, erg.|Contraditório.","Hoor!|Incompleto."], "Atenção: «Vind je het erg?» → «Nee hoor» = não me importo.", ["v-nee-hoor"]),
